export async function placeBooking(seat: string, account: string) {
  const result = await fetch("/v2/bookings", {
    method: "POST", headers: { "X-Seat-Account": account }, body: JSON.stringify({ seat }),
  });
  return result.json();
}

booking-service.java/Reservations.java:
record BookingPlaced(String seat, String account) {}
interface EventPublisher { void publish(String topic, String key, BookingPlaced event); }
final class Reservations {
  private final EventPublisher publisher;
  Reservations(EventPublisher publisher) { this.publisher = publisher; }
  void place(String seat, String account) {
    var event = new BookingPlaced(seat, account);
    publisher.publish("booking.placed.v2", account, event);
  }
}

booking-ledger.java/BookingConsumer.java:
record BookingPlaced(String seat, String account) {}
record SeatKey(String account, String seat) {}
interface MongoCollection { void replaceOne(SeatKey selector, BookingPlaced document, boolean upsert); }
interface KafkaSubscriber { void subscribe(String topic, String group, BookingConsumer handler); }
final class BookingConsumer {
  private final MongoCollection collection;
  BookingConsumer(MongoCollection collection) { this.collection = collection; }
  void start(KafkaSubscriber subscriber, String group) { subscriber.subscribe("booking.placed.v2", group, this); }
  void onMessage(BookingPlaced event) {
    var selector = new SeatKey(event.account(), event.seat());
    collection.replaceOne(selector, event, true);
  }
}
